$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION day_facts_reject_closed_day() RETURNS TRIGGER AS $$
DECLARE day_state TEXT;
BEGIN
  SELECT state INTO day_state FROM days
